  'mergesteps-p4' => 'ከማጠናቀቅዎ በፊት ቅድመ-እይታ። ትዕዛዙ ትክክል መሆኑን እና ሁሉም ገጾች መካተታቸውን ለማረጋገጥ የተዋሃደ ቅድመ እይታን ይገምግሙ።',
  'splitsteps-heading' => 'ደረጃ በደረጃ፡ ፒዲኤፎችን መከፋፈል',
  'splitsteps-p1' => '__SPLIT_LINK__ን በመጠቀም፡ ፒዲኤፍ ስቀል። ለማውጣት ገጾችን ይግለጹ። አማራጮች የተወሰኑ የገጽ ክልሎችን ማውጣት፣ እያንዳንዱን Nth ገጽ ማውጣት ወይም በመመዘኛዎች ላይ ተመስርተው ገጾችን ማውጣትን ያካትታሉ።',
  'splitsteps-p2' => 'የወጡ ገጾችን እንደ የተለየ ፒዲኤፍ አውርድ። አንዳንድ መሳሪያዎች ብዙ የውጤት ፋይሎችን (በአንድ በተወጣው ክፍል አንድ) ወይም ነጠላ ፋይል ከተመረጡ ገጾች ጋር ​​ያቀርባሉ።',
